draw:
var Patm = p.patm, hHg = p.hg, L1 = p.len;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var scale = (H - 70) / (Patm > 100 ? Patm : 100) * 1.1;
var tubeW = Math.min(26, W * 0.07);
var ok = (Patm - hHg) > 1;
var L2 = ok ? L1 * (Patm + hHg) / (Patm - hHg) : 0;

function tube(cx, base, airLen, mercLen, closedDown, label) {
  var aPx = airLen * scale, mPx = mercLen * scale;
  var total = aPx + mPx + 18;
  // glass walls
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx - tubeW / 2, base - total);
  ctx.lineTo(cx - tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base - total);
  ctx.stroke();
  // seal the closed end
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 3;
  ctx.beginPath();
  if (closedDown) { ctx.moveTo(cx - tubeW / 2, base); ctx.lineTo(cx + tubeW / 2, base); }
  else { ctx.moveTo(cx - tubeW / 2, base - total); ctx.lineTo(cx + tubeW / 2, base - total); }
  ctx.stroke();
  var airTop, mercTop;
  if (closedDown) { airTop = base - aPx; mercTop = airTop - mPx; }
  else { airTop = base - total; mercTop = airTop + aPx; }
  // air column
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - tubeW / 2 + 1, closedDown ? airTop : airTop, tubeW - 2, aPx);
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  ctx.strokeRect(cx - tubeW / 2 + 1, airTop, tubeW - 2, aPx);
  // mercury
  ctx.fillStyle = C.figure;
  ctx.fillRect(cx - tubeW / 2 + 1, mercTop, tubeW - 2, mPx);
  // labels
  ctx.fillStyle = C.ink;
  ctx.fillText(label, cx, base + 16);
  ctx.textAlign = "left";
  ctx.fillStyle = C.accent;
  ctx.fillText("air " + airLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, airTop + aPx / 2 + 4);
  ctx.fillStyle = C.figure;
  ctx.fillText("Hg " + mercLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, mercTop + mPx / 2 + 4);
  ctx.textAlign = "center";
}

var base = H - 26;
tube(W * 0.24, base, L1, hHg, true, "closed end down");
if (ok) {
  tube(W * 0.66, base, L2, hHg, false, "closed end up");
} else {
  ctx.fillStyle = C.ink;
  ctx.fillText("mercury would be pushed out", W * 0.68, H * 0.5);
}
// pressure annotations
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("P = " + (Patm + hHg).toFixed(0) + " cmHg", W * 0.24, 16);
if (ok) ctx.fillText("P = " + (Patm - hHg).toFixed(0) + " cmHg", W * 0.66, 16);

out.note = ok
  ? "P1 = " + (Patm + hHg).toFixed(1) + " cmHg, P2 = " + (Patm - hHg).toFixed(1) + " cmHg, so L2 = L1 x P1/P2 = " + L2.toFixed(2) + " cm"
  : "Impossible: the mercury column exceeds the atmosphere, so it cannot hang there.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cols = 3;
var colW = W / cols;
var cy = H * 0.38;
var titles = ["Monatomic", "Diatomic, cool", "Diatomic, hot"];
var fs = [3, 5, 7];
var notes = ["3 translational", "3 translational + 2 rotational", "3 trans + 2 rot + 2 vibrational"];
var gam = ["5/3", "7/5", "9/7"];

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 6 * Math.cos(a - 0.4), y2 - 6 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 6 * Math.cos(a + 0.4), y2 - 6 * Math.sin(a + 0.4));
  ctx.closePath();
  ctx.fillStyle = col; ctx.fill();
}

for (var i = 0; i < cols; i++) {
  var cx = colW * (i + 0.5);
  ctx.fillStyle = C.ink;
  ctx.fillText(titles[i], cx, 18);
  if (i === 0) {
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(cx, cy, 11, 0, 6.2832); ctx.fill();
  } else {
    var sep = i === 2 ? 26 : 22;
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(cx - sep / 2, cy, 9, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + sep / 2, cy, 9, 0, 6.2832); ctx.fill();
    if (i === 1) {
      ctx.strokeStyle = C.rule; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(cx - sep / 2, cy); ctx.lineTo(cx + sep / 2, cy); ctx.stroke();
    } else {
      // spring bond for the vibrating case
      ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(cx - sep / 2, cy);
      for (var k = 1; k <= 6; k++) {
        ctx.lineTo(cx - sep / 2 + sep * k / 6, cy + (k % 2 === 0 ? -5 : 5) * (k === 6 ? 0 : 1));
      }
      ctx.lineTo(cx + sep / 2, cy);
      ctx.stroke();
      arrow(cx - sep / 2 - 4, cy + 20, cx - sep / 2 - 14, cy + 20, C.accent);
      arrow(cx + sep / 2 + 4, cy + 20, cx + sep / 2 + 14, cy + 20, C.accent);
      ctx.fillStyle = C.accent;
      ctx.fillText("stretch", cx, cy + 38);
    }
  }
  // translational arrows, same for every case
  arrow(cx, cy, cx + 30, cy, C.accent);
  arrow(cx, cy, cx, cy - 26, C.accent);
  arrow(cx, cy, cx - 21, cy + 18, C.accent);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "left";
  ctx.fillText("x", cx + 33, cy + 4);
  ctx.textAlign = "center";
  ctx.fillText("z", cx, cy - 31);
  ctx.fillText("y", cx - 27, cy + 26);
  if (i > 0) {
    // rotation arcs
    ctx.strokeStyle = C.ink; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(cx, cy, 24, -0.6, 0.9); ctx.stroke();
    ctx.fillStyle = C.ink;
    ctx.fillText("2 rot", cx + 38, cy - 20);
  }
  ctx.fillStyle = C.ink;
  ctx.fillText(notes[i], cx, H - 42);
  ctx.fillText("f = " + fs[i] + ",  C_V = " + (fs[i] / 2).toFixed(1) + "R", cx, H - 26);
  ctx.fillStyle = C.faint;
  ctx.fillText("gamma = " + gam[i], cx, H - 10);
  if (i < cols - 1) {
    ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(colW * (i + 1), 26); ctx.lineTo(colW * (i + 1), H - 54); ctx.stroke();
  }
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = p.gamma, r = p.ratio, T1 = p.temp;
// animate the piston in and back out
var phase = 0.5 - 0.5 * Math.cos(t * 0.7);
var x = 1 + phase * (r - 1);          // compression so far
var V = 1 / x;                        // volume in units of V1
var T = T1 * Math.pow(x, g - 1);
var P = Math.pow(x, g);               // pressure in units of P1

// ---- cylinder on the left ----
var cx0 = 14, cx1 = W * 0.42, cyTop = H * 0.22, cyBot = H * 0.62;
var pistonX = cx0 + (cx1 - cx0) * V;
ctx.fillStyle = C.paper;
ctx.fillRect(cx0, cyTop, pistonX - cx0, cyBot - cyTop);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx1, cyTop); ctx.lineTo(cx0, cyTop);
ctx.lineTo(cx0, cyBot); ctx.lineTo(cx1, cyBot);
ctx.stroke();
// gas molecules, deterministic drift inside the shrinking box
ctx.fillStyle = C.accent;
for (var i = 0; i < 16; i++) {
  var sx = ((i * 0.3793 + t * (0.18 + 0.03 * (i % 5))) % 1);
  var sy = ((i * 0.6271 + t * (0.23 + 0.04 * (i % 3))) % 1);
  sx = sx < 0.5 ? sx * 2 : 2 - sx * 2;
  sy = sy < 0.5 ? sy * 2 : 2 - sy * 2;
  var mx = cx0 + 5 + sx * (pistonX - cx0 - 10);
  var my = cyTop + 5 + sy * (cyBot - cyTop - 10);
  ctx.beginPath(); ctx.arc(mx, my, 2.4, 0, 6.2832); ctx.fill();
}
// piston
ctx.fillStyle = C.figure;
ctx.fillRect(pistonX, cyTop, 8, cyBot - cyTop);
ctx.fillRect(pistonX + 8, (cyTop + cyBot) / 2 - 3, cx1 - pistonX - 8, 6);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("insulated cylinder", (cx0 + cx1) / 2, cyTop - 10);
ctx.fillText("T = " + T.toFixed(0) + " K", (cx0 + cx1) / 2, cyBot + 20);

// ---- PV diagram on the right ----
var gx0 = W * 0.55, gx1 = W - 52, gy0 = 22, gy1 = H - 30;
var Pmax = Math.pow(r, g);
function px(v) { return gx0 + (1 - (v - 1 / r) / (1 - 1 / r)) * 0 + ((v - 1 / r) / (1 - 1 / r)) * (gx1 - gx0); }
function py(pp) { return gy1 - ((pp - 1) / (Pmax - 1)) * (gy1 - gy0); }
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("volume", (gx0 + gx1) / 2, gy1 + 18);
ctx.save();
ctx.translate(gx0 - 12, (gy0 + gy1) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("pressure", 0, 0);
ctx.restore();

function curve(expn, col, dash) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.8;
  ctx.setLineDash(dash);
  ctx.beginPath();
  for (var i = 0; i <= 60; i++) {
    var vv = 1 / r + (1 - 1 / r) * i / 60;
    var pp = Math.pow(1 / vv, expn);
    if (i === 0) ctx.moveTo(px(vv), py(pp)); else ctx.lineTo(px(vv), py(pp));
  }
  ctx.stroke();
  ctx.setLineDash([]);
}
curve(1, C.faint, [4, 4]);
curve(g, C.accent, []);
ctx.textAlign = "left";
ctx.fillStyle = C.faint;
ctx.fillText("isotherm", gx1 - 96, py(r) - 6);
ctx.fillStyle = C.accent;
ctx.fillText("adiabat", gx1 - 46, gy0 + 22);
// moving state point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px(V), py(P), 4, 0, 6.2832); ctx.fill();

out.note = "V1/V2 = " + r.toFixed(1) + ": final T = " + (T1 * Math.pow(r, g - 1)).toFixed(0)
  + " K and P2/P1 = " + Pmax.toFixed(1) + " (an isotherm would give only " + r.toFixed(1) + ")";
